import React, { useState, useEffect } from 'react';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faShoppingCart, faTrash } from '@fortawesome/free-solid-svg-icons';
import { FaEye, FaEyeSlash, FaEdit, FaSave, FaTimes } from 'react-icons/fa';
import './ZapatosCard.css';
import { useDispatch, useSelector } from 'react-redux';
import { addToCart, removeFromCart } from '../../../Carrito/Carrito_Localstorang/CaritoLocalstorang';
import { Activar_Ocultar_Cards, Actualiza_Card } from '../../../../Redux/Actions/Empresa/Actions-Empresa';
import alertify from 'alertifyjs';
import 'alertifyjs/build/css/alertify.css';

const ZapatosCard = ({
  id,
  tienda,
  marca,
  costo,
  color,
  modelo,
  calidad,
  descripcion,
  url,
  talla,
  activo
}) => {
  const User = useSelector((state) => state.USER);
  const dispatch = useDispatch();

  const [isEditing, setIsEditing] = useState(false);
  const [formData, setFormData] = useState({
    color: color || '',
    talla: talla || '',
    costo: costo || '',
    marca: marca || '',
    modelo: modelo || '',
    calidad: calidad || ''
  });
  const [cartItems, setCartItems] = useState([]);
  const [stadobtn, setStatebtn] = useState(false);

  const colores = useSelector((state) => state.COLORES || []);
  const tallas = useSelector((state) => state.TALLAS || []);
  const marcas = useSelector((state) => state.MARCAS || []);
  const calidades = useSelector((state) => state.CALIDAD || []);
  const categorias = useSelector((state) => state.CATEGORIAS || []);

  useEffect(() => {
    const items = JSON.parse(localStorage.getItem('cartItems')) || [];
    setCartItems(items.map(item => item.id));
    setStatebtn(activo === "true");
  }, [activo]);

  const handleActivar = async (id) => {
    const dato = await dispatch(Activar_Ocultar_Cards(id));
    alert("Activar " + dato);
    setStatebtn(true);
  };

  const handleOcultar = async (id) => {
    const dato = await dispatch(Activar_Ocultar_Cards(id));
    alert("Ocultar " + dato);
    setStatebtn(false);
  };

  const handleAddToCart = () => {
    const item = {
      id,
      marca,
      tienda,
      costo,
      color,
      modelo,
      calidad,
      descripcion,
      url,
      talla,
      quantity: 1
    };
    addToCart(item);
    setCartItems([...cartItems, id]);
    alert("Producto agregado al carrito");
  };

  const handleRemoveFromCart = () => {
    removeFromCart(id);
    setCartItems(cartItems.filter(itemId => itemId !== id));
    alert("Producto eliminado del carrito");
  };

  const handleModificar = () => {
    setIsEditing(true);
  };

  const handleSave = async () => {
    // Validar que todos los campos estén llenos
    if (
      !formData.color ||
      !formData.talla ||
      !formData.costo ||
      !formData.marca ||
      !formData.modelo ||
      !formData.calidad
    ) {
      alertify.alert('Mensaje', 'Faltan datos en el formulario');
      return;
    }

    const datos = await dispatch(Actualiza_Card(id, tienda, formData));
    alertify.alert("El proceso fue", datos);
    setIsEditing(false);
    alert("Cambios guardados");
  };

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData({ ...formData, [name]: value });
  };

  return (
    <div className="zapatos-card" title={id}>
      <img src={url} alt="Zapato" className="zapatos-image" />
      <div className="zapatos-info">
        <div className='titulo-zapato'>
          <p className='black-text'>Marca: </p>
          {isEditing ? (
            <select
              name="marca"
              value={formData.marca}
              onChange={handleChange}
              className='input-card-peque'
            >
              <option value="">Seleccione una marca</option>
              {marcas.map((m) => (
                <option key={m.id} value={m.marca}>
                  {m.marca}
                </option>
              ))}
            </select>
          ) : (
            marca
          )}
        </div>
        <div className="zapatos-price">
          <div className='parrafo-flex'>
            <p className='black-text'>Calidad:</p>
            {isEditing ? (
              <select
                name="calidad"
                value={formData.calidad}
                onChange={handleChange}
                className='input-card-peque'
              >
                <option value="">Seleccione una calidad</option>
                {calidades.map((m) => (
                  <option key={m.id} value={m.calidad}>
                    {m.calidad}
                  </option>
                ))}
              </select>
            ) : (
              calidad
            )}
            <p className='black-text'> Categorias:</p>
            {isEditing ? (
              <select
                name="modelo"
                value={formData.modelo}
                onChange={handleChange}
                className='input-card-peque'
              >
                <option value="">Seleccione una categoria</option>
                {categorias.map((m) => (
                  <option key={m.id} value={m.modelo}>
                    {m.modelo}
                  </option>
                ))}
              </select>
            ) : (
              modelo
            )}
          </div>
          <div className='parrafo-flex'>
            <p className='black-text'>Talla:</p>
            {isEditing ? (
              <select
                name="talla"
                value={formData.talla}
                onChange={handleChange}
                className='input-card-peque'
              >
                <option value="">Seleccione una talla</option>
                {tallas.map((t) => (
                  <option key={t.id} value={t.talla}>
                    {t.talla}
                  </option>
                ))}
              </select>
            ) : (
              talla
            )}
            <p className='black-text'> Color:</p>
            {isEditing ? (
              <select
                name="color"
                value={formData.color}
                onChange={handleChange}
                className='input-card-peque'
              >
                <option value="">Seleccione un color</option>
                {colores.map((color) => (
                  <option key={color.id} value={color.color}>
                    {color.color}
                  </option>
                ))}
              </select>
            ) : (
              color
            )}
          </div>
          <div className='parrafo-flex'>
            <p className='black-text'>Costo:</p>
            {isEditing ? (
              <input
                type="text"
                name="costo"
                value={formData.costo}
                onChange={handleChange}
                className='input-card-peque'
              />
            ) : (
              `$ ${costo}`
            )}
          </div>
        </div>
        {User.state === "true" ? (
          <div>
            {isEditing ? (
              <button className="zapatos-btn-Activar" onClick={() => handleSave()}>
                <FaSave className="icon" title='Guardar' />
              </button>
            ) : (
              isInCart ? (
                <button className="zapatos-btn-Eliminar" onClick={() => handleRemoveFromCart()}>
                  <FontAwesomeIcon icon={faTrash} className="icon" /> Eliminar del carrito
                </button>
              ) : (
                <button className="zapatos-btn" onClick={() => handleAddToCart()}>
                  <FontAwesomeIcon icon={faShoppingCart} className="cart-icon" />
                  Agregar al carrito
                </button>
              )
            )}
            <button className="zapatos-btn-Activar" onClick={() => setIsEditing(!isEditing)}>
              {isEditing ? <FaTimes className="icon" title='Cancelar' /> : <FaEdit className="icon" title='Editar' />}
            </button>
          </div>
        ) : stadobtn ? (
          <div className='display-felx-btn'>
            <button className="zapatos-btn-Activar" onClick={() => handleOcultar(id)}>
              <FaEye className="icon" title='Ver Tarjeta' />
            </button>
            <button className="zapatos-btn-Activar" onClick={() => handleDelete(id)}>
              <FaTimes className="icon" title='Eliminar Tarjeta' />
            </button>
            {isEditing ? (
              <button className="zapatos-btn-Activar" onClick={() => handleSave(id)}>
                <FaSave className="icon" title='Guardar' />
              </button>
            ) : (
              <button className="zapatos-btn-Activar" onClick={() => handleModificar()}>
                <FaEdit className="icon" title='Editar Textos' />
              </button>
            )}
          </div>
        ) : (
          <button className="zapatos-btn-Ocultar" onClick={() => handleActivar(id)}>
            <FaEyeSlash className="icon" title='Ocultar Tarjeta' />
          </button>
        )}
      </div>
    </div>
  );
}

export default ZapatosCard;
